 static string Tr(string x){switch(x){case "single_report_research_note":return "Одиночная исследовательская заметка";case "repeated_wording_candidate; needs buyer validation":return "Повторение формулировок; покупатель не подтверждён";case "multiple_reports_unconfirmed_theme":return "Несколько сообщений; общая проблема не подтверждена";case "no_observed_problem_report":return "Сообщений о проблеме не установлено";case "not_established":return "Не установлена";case "Fewer than two distinct problem reports: not evidence of a repeatable market problem":return "Менее двух сообщений о проблеме: повторяемость не доказана";case "No repeated specific title/excerpt wording established across supplied references":return "Повторение конкретных формулировок не установлено";case "Independent confirmation is unknown":return "Независимые подтверждения неизвестны";case "No current, matched public alternative price verified":return "Подходящая актуальная публичная цена не подтверждена";case "Who actually pays and willingness to pay are unverified":return "Плательщик и готовность платить не подтверждены";case "No completed purchase, representative demand or unit economics observed":return "Фактических покупок, репрезентативного спроса и экономики нет";case "Some requested sources failed; coverage is incomplete":return "Часть источников недоступна; охват неполный";case "Some observations are stale or undated; do not treat historical questions as current demand":return "Часть наблюдений устарела либо не датирована; это не текущий спрос";case "Price snippets do not establish the applicable plan, region, billing commitment, taxes or feature equivalence":return "Цена не подтверждает сопоставимость функций, тариф, регион, налоги и обязательство оплаты";default:return x;}}
 static IEnumerable<object> Items(Dictionary<string,object> d,string k){if(d.ContainsKey(k)&&d[k] is IEnumerable&&!(d[k] is string))foreach(object x in (IEnumerable)d[k])yield return x;}
