 void ShowCard(){
  if(cards==null||detail==null||detail.IsDisposed)return;
  var outcomeRow=cards.SelectedItem as AnalysisOutcomeRow;if(outcomeRow!=null){decisionExpectedKey=null;decisionExpectedPin=null;if(historyView)historySelectionId="job:"+outcomeRow.Entry.JobId;detail.Text=outcomeRow.Entry.Text;return;}
  var audit=cards.SelectedItem as AuditRow;if(audit!=null){detail.Text=audit.Entry.Text;return;}
  var source=cards.SelectedItem as SourceRow;if(source!=null){sourceSelectionId=SourceIdentity(source.Data);try{ShowSource(source.Data);}catch(Exception ex){if(ex is OutOfMemoryException)throw;detail.Text="Источник не отображён: "+ex.GetType().Name+": "+ex.Message+"\r\nИсходная запись не изменена; выберите другой источник.";}return;}
  var item=cards.SelectedItem as Card;if(item==null)return;if(historyView)historySelectionId=CardIdentity(item.Data);
  try{RenderCard(item.Data);}catch(Exception ex){if(ex is OutOfMemoryException)throw;detail.Text="Неполная запись истории: "+ex.GetType().Name+": "+ex.Message+"\r\nФайл не изменён. Другие записи доступны.\r\n"+DecisionStore.DescribeRecovery(root,S(item.Data,"candidate_id"),S(item.Data,"review_revision_hash"));}
 }
 void RenderCard(Dictionary<string,object> c){decisionExpectedKey=null;decisionExpectedPin=null;var b=new StringBuilder(ResearchRunPresentation.Describe(last)+"\r\n");if(historyView&&historyWarning!="")b.AppendLine(historyWarning).AppendLine();
  b.AppendLine(OfficialObservationPresentation.Describe(root,S(c,"candidate_id"),S(c,"review_revision_hash")));
  b.AppendLine(SourceTaskPresentation.Describe(Obj(c.ContainsKey("direct_alternatives")?c["direct_alternatives"]:null)));
  if(c.ContainsKey("output_review"))AppendOutputReview(b,Obj(c["output_review"]));
  if(c.ContainsKey("assistant_source_review"))AppendAssistantSourceReview(b,Obj(c["assistant_source_review"]));
  if(c.ContainsKey("public_validation")){if(!c.ContainsKey("buyer_demand_review"))b.AppendLine("Неполная запись публичной проверки: данные покупателя отсутствуют; подтверждения нет. Файл не изменён.");AppendPublicValidation(b,Obj(c["public_validation"]),Obj(c.ContainsKey("buyer_demand_review")?c["buyer_demand_review"]:null));}
  b.AppendLine(S(c,"title")).AppendLine("ГИПОТЕЗА: спрос, продажи и прибыль не подтверждены.").AppendLine();
  foreach(var pair in new[]{new[]{"buyer","Предполагаемый покупатель"},new[]{"problem_hypothesis","Гипотеза проблемы"},new[]{"solution_hypothesis","Предлагаемое решение"},new[]{"alternatives_and_limits","Альтернативы и ограничения"},new[]{"validation_step","Как проверить"}})b.AppendLine(pair[1]+": "+S(c,pair[0])).AppendLine();
  PriceExperimentPresentation.Append(b,c);
  if(!c.ContainsKey("output_review"))b.AppendLine(LegacyCandidateReviews.Describe(root,c));
  b.AppendLine("РИСКИ:");foreach(var x in Items(c,"risks"))b.AppendLine("• "+x);
  b.AppendLine("НЕДОСТАЮЩИЕ ДОКАЗАТЕЛЬСТВА:");foreach(var x in Items(c,"missing_evidence"))b.AppendLine("• "+x);
  if(Items(c,"public_research_versions").Any())b.AppendLine("Доступна новая версия сохранённых материалов и ручного сравнения: кнопка «Материалы и сравнение». Прежний разбор и его незавершённые задачи ниже — исторические; даты источников смотрите в новой версии.");
  AppendDirect(b,Obj(c.ContainsKey("direct_alternatives")?c["direct_alternatives"]:null));
  var review=Obj(c.ContainsKey("commercial_review")?c["commercial_review"]:null);var corroboration=Obj(review.ContainsKey("corroboration")?review["corroboration"]:null);
  b.AppendLine().AppendLine(review.Count>0?"КОММЕРЧЕСКИЙ ОТБОР: "+Tr(S(review,"evidence_status")):"Коммерческая проверка: спрос и оплата не установлены").AppendLine("Уверенность низкая: фактический покупатель и оплата не установлены.");
  b.AppendLine(OfficialObservationPresentation.Describe(root,S(c,"candidate_id"),S(c,"review_revision_hash")));
  b.AppendLine(SourceTaskPresentation.Describe(Obj(c.ContainsKey("direct_alternatives")?c["direct_alternatives"]:null)));
  if(c.ContainsKey("output_review"))b.AppendLine("Категория, предложенная моделью (гипотеза): "+S(c,"market_category"));else b.AppendLine("Категория по источникам: "+S(c,"market_category")+"; предложение модели: "+S(c,"model_market_category"));
  if(corroboration.Count==0){var basis=Items(c,"observed_basis").Select(Obj).ToArray();var authors=basis.Where(x=>S(x,"author_id")!="").Select(x=>S(x,"source")+":"+S(x,"author_id")).Distinct().Count();b.AppendLine("Сохранённых наблюдений: "+basis.Length+"; записанных ID автора в namespace источника: "+authors+". Это не число независимых людей или покупателей.");}else b.AppendLine(CorroborationPresentation.Describe(corroboration));
  if(corroboration.Count==0)b.AppendLine("Независимость сообщений, людей и спроса не установлена.");
  b.AppendLine("СМЕЖНЫЕ ПУБЛИЧНЫЕ ПРЕДЛОЖЕНИЯ: функциональная сопоставимость проверяется отдельно.");var alternatives=Items(review,"existing_solutions").ToArray();if(alternatives.Length==0)b.AppendLine("Подходящие актуальные цены не получены. Это неизвестное, а не отсутствие конкуренции.");
  foreach(var priceEntry in alternatives)AppendPrice(b,Obj(priceEntry));
  var nonbasePrices=Items(review,"non_base_price_observations").ToArray();if(nonbasePrices.Length>0)b.AppendLine("Скидки, комиссии и доплаты: не базовая цена подписки:");foreach(var entry in nonbasePrices)AppendPrice(b,Obj(entry));
  var historicalPrices=Items(review,"historical_or_unverified_solution_leads").ToArray();if(historicalPrices.Length>0)b.AppendLine("Исторические/неподтверждённые по дате ценовые наблюдения — не текущие тарифы:");foreach(var priceEntry in historicalPrices)AppendPrice(b,Obj(priceEntry));
  b.AppendLine("СОПОСТАВИМОСТЬ КОНКУРЕНТОВ ПО ФУНКЦИИ И ПОКУПАТЕЛЮ:");var matches=Items(c,"functional_comparisons").ToArray();if(matches.Length==0){var direct=Obj(c.ContainsKey("direct_alternatives")?c["direct_alternatives"]:null);b.AppendLine("Сохранённая оценка документов: "+DirectStatus(S(direct,"status"))+". Техническая метка не доказывает замену исходной задачи.");}foreach(var entry in matches)AppendMatch(b,Obj(entry));
  if(c.ContainsKey("buyer_demand_review"))AppendBuyer(b,Obj(c["buyer_demand_review"]));
  b.AppendLine("ОСТАВШЕЕСЯ НЕИЗВЕСТНОЕ:");foreach(var x in Items(review,"unknowns"))b.AppendLine("• "+Tr(Convert.ToString(x)));
  string recoveryIssue=DecisionStore.RecoveryIssue(root);if(recoveryIssue!=""){b.AppendLine(DecisionStore.DescribeRecovery(root,S(c,"candidate_id"),S(c,"review_revision_hash")));}else{var notes=DecisionStore.Read(root);string id=S(c,"candidate_id");decisionExpectedKey=id+"@"+S(c,"review_revision_hash");decisionExpectedPin=DecisionStore.EntryPin(notes,id);if(notes.ContainsKey(id)){var n=Obj(notes[id]);b.AppendLine("Saved owner decision: "+S(n,"decision")+" | "+(S(n,"revision_hash")==S(c,"review_revision_hash")?"selected revision":"different revision; review again")+". Owner preference only.");}}

  foreach(var freshnessEntry in Items(review,"observation_freshness")){var f=Obj(freshnessEntry);b.AppendLine("Актуальность при оценке: "+S(f,"status")+" | "+S(f,"url"));}
  b.AppendLine().AppendLine("ФАКТИЧЕСКИЕ НАБЛЮДЕНИЯ И ИСТОЧНИКИ:");
  foreach(var x in Items(c,"observed_basis"))AppendObservedSource(b,Obj(x));
  b.AppendLine("Источник сообщает только показанные наблюдения. Объяснения модели, покупатель и преимущества — гипотезы. Репрезентативность, готовность платить и правовые вопросы не проверены.");detail.Text=b.ToString();
 }
 static void AppendBuyer(StringBuilder b,Dictionary<string,object> review){b.AppendLine("ПОКУПАТЕЛЬ И СПРОС: публичные самоотчёты, не подтверждённые клиенты").AppendLine("Плательщик: неизвестен. Оплата нашего решения: не подтверждена.");foreach(var item in Items(review,"original_reports")){var report=Obj(item);b.AppendLine(BuyerSourcePresentation.Describe(report));b.AppendLine(S(report,"source_url")).AppendLine("Получено: "+S(report,"observed_at")+" | "+Freshness(S(report,"observed_at"),43200)).AppendLine("Ответ/решение: "+S(report,"answer_status"));if(report.ContainsKey("error"))b.AppendLine("Источник недоступен: "+S(report,"error"));foreach(var fact in Items(report,"facts")){var f=Obj(fact);b.AppendLine(S(f,"kind")+": "+S(f,"quote"));}}foreach(var x in Items(review,"unknowns"))b.AppendLine("• "+x);b.AppendLine("Уже имеющийся ответ не доказывает полного решения; вопрос сам по себе не доказывает спрос. Результат эвристической проверки не устанавливает отсутствие бюджета.");}
 void ShowBuyer(){if(last==null)return;var b=new StringBuilder();foreach(var item in Items(last,"hypotheses")){var card=Obj(item);b.AppendLine(S(card,"title"));AppendBuyer(b,Obj(card.ContainsKey("buyer_demand_review")?card["buyer_demand_review"]:null));b.AppendLine();}detail.Text=b.ToString();}
 static string Freshness(string stamp,int seconds){DateTimeOffset date;if(!DateTimeOffset.TryParse(stamp,out date))return "дата неизвестна";double age=(DateTimeOffset.UtcNow-date.ToUniversalTime()).TotalSeconds;return age>=0&&age<=seconds?"в пределах срока приложения":"устарело либо дата из будущего";}
 static string Relation(string x){switch(x){case "same-task":return "та же задача";case "same":return "тот же предполагаемый сегмент";case "adjacent":return "смежная";case "unrelated":return "другая задача / не сопоставима";default:return "неизвестно";}}
 static void AppendObservedSource(StringBuilder b,Dictionary<string,object> o){
  b.AppendLine(S(o,"evidence_id")+" | "+S(o,"source")+" | "+S(o,"kind")).AppendLine(S(o,"title"));
  bool titleOnly=S(o,"kind")=="public_topic_title"||S(o,"kind")=="public_question_title";
  if(titleOnly)b.AppendLine("Сохранён только заголовок; исходный текст неизвестен. Ограничение старого сборщика: "+S(o,"excerpt"));
  else b.AppendLine(S(o,"context_text")!=""?S(o,"context_text"):S(o,"excerpt"));
  b.AppendLine(S(o,"url")).AppendLine("Область текста: "+(S(o,"content_scope")!=""?S(o,"content_scope"):"сохранённый исторический фрагмент; полнота неизвестна")).AppendLine("Усечение: "+(S(o,"context_truncated")!=""?S(o,"context_truncated"):"неизвестно"));
  if(S(o,"context_text_sha256")!="")b.AppendLine("SHA сохранённого текста: "+S(o,"context_text_sha256"));
  b.AppendLine("Получено: "+S(o,"observed_at")+" | Сейчас: "+Freshness(S(o,"observed_at"),3600));AppendAnswerContext(b,o);AppendMediaScope(b,o);b.AppendLine();
 }
 static void AppendPublicValidation(StringBuilder b,Dictionary<string,object> validation,Dictionary<string,object> buyer){
  if(S(validation,"review_mode")=="saved_material_only_no_freshness_renewal")b.AppendLine("АРХИВНЫЙ РАЗБОР ПУБЛИЧНЫХ МАТЕРИАЛОВ: новых запросов не было; даты/сроки источников не обновлялись.").AppendLine("Это не подтверждённые покупатели, не новая актуальная проверка и не семантическое одобрение AI.");
  foreach(var taskEntry in Items(validation,"next_evidence_tasks")){var task=Obj(taskEntry);b.AppendLine("ПЛАН СБОРА: "+(S(task,"kind")=="read_original_public_source"?"Прочитать исходный публичный материал":"Проверить альтернативы по исходной задаче")+" | "+S(task,"url")).AppendLine(S(task,"reason"));if(S(task,"execution_blocker")!="")b.AppendLine("Блокер выполнения: новые обращения к внешним источникам отклонены проверкой разрешений; архивный материал остаётся доступен.");}

  b.AppendLine(S(validation,"status")=="public_checks_completed"||S(validation,"status")=="public_material_collection_unreviewed"?"Публичные материалы собраны. Смысл, пригодность решения и спрос автоматически НЕ проверены.":"Сохранённые публичные материалы: актуальность/доступность и смысловой разбор требуют проверки.");
