  if(S(o,"answer_text")!="")b.AppendLine(S(o,"answer_url")).AppendLine(S(o,"answer_text")).AppendLine("Объём ответа: "+S(o,"answer_text_chars")+"; обрезан: "+S(o,"answer_text_truncated")).AppendLine("SHA ответа: "+S(o,"answer_text_sha256"));
  if(S(o,"answer_collection_limitation")!="")b.AppendLine("Ограничение сбора ответа: "+S(o,"answer_collection_limitation"));
  b.AppendLine();
 }
 static void AppendMediaScope(StringBuilder b,Dictionary<string,object> o){
