  string currentAnalysis=CurrentAnalysisNote(result);resultStatus=(currentAnalysis!=""?"Сохранённый сбор | "+currentAnalysis:S(result,"status")+" | "+S(result,"note"))+" | HTTP: "+S(result,"source_requests")+", кэш источников: "+S(result,"source_cache_hits")+", Qwen: "+S(result,"model_requests");var discovery=Obj(result.ContainsKey("discovery_summary")?result["discovery_summary"]:null);if(discovery.Count>0)resultStatus+=" | Сбор: новых "+S(discovery,"new_to_history")+", изменено "+S(discovery,"updated_existing")+", повторов "+S(discovery,"unchanged_seen")+", всего URL "+S(discovery,"history_records");resultStatus=ResearchRunPresentation.Status(result)+" | "+resultStatus;status.Text=resultStatus+PendingAnalysis();
  if(historyView){LoadHistory(false);return;}
  string selected=cards.SelectedItem is Card?CardIdentity(((Card)cards.SelectedItem).Data):"";
  cards.Items.Clear();foreach(var c in Items(result,"hypotheses"))cards.Items.Add(new Card{Data=Obj(c)});
  if(cards.Items.Count>0){int found=Enumerable.Range(0,cards.Items.Count).FirstOrDefault(i=>HistoryIdentity(cards.Items[i])==selected);cards.SelectedIndex=found;}
  else {var rawObservations=Items(result,"observations").ToArray();var observations=rawObservations.Select(x=>x as Dictionary<string,object>).Where(x=>x!=null).ToArray();if(rawObservations.Length!=observations.Length)status.Text+=" Пропущены нечитаемые записи источников: "+(rawObservations.Length-observations.Length)+"; файл не изменён.";cards.BeginUpdate();try{foreach(var row in observations)cards.Items.Add(new SourceRow{Data=row});if(cards.Items.Count>0){int found=Enumerable.Range(0,cards.Items.Count).FirstOrDefault(i=>SourceIdentity(((SourceRow)cards.Items[i]).Data)==sourceSelectionId);cards.SelectedIndex=found;}else{var text=new StringBuilder(status.Text);foreach(var error in Items(result,"source_errors")){var item=Obj(error);text.AppendLine().Append(S(item,"source")+": "+S(item,"reason"));}detail.Text=text.ToString();}}finally{cards.EndUpdate();}}

 }
