 static Dictionary<string,object> Read(string path){return LocalJson.ReadObject(path);}
 void Start(){if(worker!=null&&!worker.HasExited)return;buyerWorker=false;StartWorker(false);}
 void StartComparison(){if(worker!=null&&!worker.HasExited)return;buyerWorker=false;StartWorker(true);}
