 string officialObservationManifest;
 void ImportOfficialObservations(){if(worker!=null&&!worker.HasExited)return;using(var dialog=new OpenFileDialog{Title="Выберите manifest.json структурированных наблюдений",Filter="Observation manifest|manifest.json",CheckFileExists=true}){if(dialog.ShowDialog(Form)!=DialogResult.OK)return;officialObservationManifest=dialog.FileName;buyerWorker=false;try{StartWorker(true);}finally{officialObservationManifest=null;}}}
 void StartWorker(bool compare){
  if(worker!=null&&!worker.HasExited){status.Text="Этот проход уже выполняется";return;}
  string issue;var py=PortableRuntime.Python(root,officialObservationManifest==null?"collect":"export",out issue);var script=Path.Combine(root,compare?(buyerWorker?"reveng_buyer_worker.py":"reveng_competitor_worker.py"):"reveng_local_research.py");comparisonWorker=compare;if(py==null||!File.Exists(script)||!PortableRuntime.Check(root,py,officialObservationManifest!=null?"export":compare?(buyerWorker?"api":"html"):"api",out issue)){status.Text="Инструменты сбора недоступны; история и источники сохранены.";detail.Text=issue+"\r\nАвтоматических скачиваний и запуска AI нет.";return;}
  runPath=Path.Combine(root,"runs","run-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(runPath);
  var info=new ProcessStartInfo(py,"-X utf8 \""+script+"\" --root \""+root+"\" --run \""+runPath+"\""+((compare&&!buyerWorker)?" --direct-only":(!compare?" --collect-only":""))+((forceOffline||transitionTest||buyerTransitionTest)?" --offline-replay":"")+(officialObservationManifest==null?"":" --official-observations \""+officialObservationManifest+"\"")){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=root,RedirectStandardOutput=true,RedirectStandardError=true};
  worker=new Process{StartInfo=info};worker.OutputDataReceived+=(s,e)=>Log("worker.log",e.Data);worker.ErrorDataReceived+=(s,e)=>Log("worker-errors.log",e.Data);worker.Start();workerStarts++;worker.BeginOutputReadLine();worker.BeginErrorReadLine();timer.Start();status.Text="Начат ограниченный проход; результаты и источники появятся здесь";
 }
 void Log(string file,string data){if(data!=null)try{File.AppendAllText(Path.Combine(runPath,file),data+Environment.NewLine,Encoding.UTF8);}catch{}}
 void Cancel(){if(worker!=null&&!worker.HasExited&&runPath!=null){File.WriteAllText(Path.Combine(runPath,"cancel.request"),"cancel");if(status!=null&&!status.IsDisposed)status.Text="Отмена запрошена; текущее чтение завершится по таймауту";}}
 void Poll(){
  if(runPath==null){timer.Stop();return;}try{string path=Path.Combine(runPath,"result.json");if(File.Exists(path)){var r=Read(path);Display(r);if(S(r,"status")!="running"&&worker.HasExited){if(S(r,"status")=="completed"&&!r.ContainsKey("discovery_summary")&&!comparisonWorker&&!forceOffline){StartComparison();return;}if(S(r,"status")=="completed"&&comparisonWorker&&!buyerWorker&&!forceOffline&&(!transitionTest||buyerTransitionTest)&&!r.ContainsKey("buyer_evidence")){StartBuyer();return;}timer.Stop();return;}}if(worker.HasExited){status.Text="Процесс завершился без итогового результата; журнал сохранён";timer.Stop();}}catch(IOException){}catch(Exception ex){status.Text="Ошибка чтения результата: "+ex.Message;timer.Stop();}
 }
 public void SelfTest(string receipt){
  if(Form.Visible)throw new Exception("Unexpected visible form");if(Freshness(DateTimeOffset.UtcNow.AddDays(-2).ToString("o"),3600)!="устарело либо дата из будущего")throw new Exception("Historical freshness wrong");OpenResearchForTest();
  var buttons=Tree(Form).OfType<Button>().ToArray();foreach(string text in new[]{"Opportunities","Research","Compare","Blueprint","Reporting"})if(!buttons.Any(b=>b.Text==text))throw new Exception("Existing navigation missing: "+text);
  if(!buttons.Any(b=>b.Name=="LocalResearchStart")||cards==null||detail==null)throw new Exception("Primary action/view missing");
  int count=cards.Items.OfType<Card>().Count();int sourceCount=cards.Items.OfType<SourceRow>().Count();if(count>0&&last!=null&&S(last,"status")=="completed"&&(count<2||!detail.Text.Contains("https://")||!detail.Text.Contains("ГИПОТЕЗА")))throw new Exception("Real results/evidence not rendered");
  if(count>0&&!detail.Text.Contains("КОММЕРЧЕСКИЙ ОТБОР"))throw new Exception("Commercial evidence fields missing");
  int historyCount=0,priceCount=0;if(count>0){ShowComparison();if(!detail.Text.Contains("ПОВТОРНАЯ ПРОВЕРКА"))throw new Exception("Comparison missing");ShowPrices();priceCount=Items(last,"public_price_records").Count();if(priceCount>0&&!detail.Text.Contains("https://"))throw new Exception("Dated pricing links missing");ShowHistory();historyCount=cards.Items.Count;if(historyCount<3)throw new Exception("History missing");}
  if(last!=null&&Items(last,"hypotheses").Any(x=>Items(Obj(x),"functional_comparisons").Any(z=>Obj(z).ContainsKey("plan_feature_mapping")))){ShowFunctional();if(!detail.Text.Contains("Тарифные функции:")||!detail.Text.Contains("$49/year")||!detail.Text.Contains("Starter"))throw new Exception("Plan source links missing");}
  if(last!=null&&Items(last,"hypotheses").Any(x=>Obj(x).ContainsKey("direct_alternatives"))){historyView=false;Display(last);cards.SelectedIndex=0;if(!detail.Text.Contains("Прямые альтернативы:")||!detail.Text.Contains("woocommerce.com/document/cash-on-delivery"))throw new Exception("Direct alternative evidence not rendered");cards.SelectedIndex=1;if(!detail.Text.Contains("Частичная альтернатива")&&!detail.Text.Contains("В проверенных источниках решение не найдено"))throw new Exception("Partial/unknown distinction missing");}
  if(sourceCount>0){if(!detail.Text.Contains("https://"))throw new Exception("Saved source not rendered");ShowHistory();historyCount=cards.Items.Count;if(historyCount<3)throw new Exception("History missing");}
  var result=new Dictionary<string,object>{{"status","PASS"},{"version",Version},{"rendered_cards",count},{"rendered_sources",sourceCount},{"historical_cards",historyCount},{"price_records",priceCount},{"commercial_fields_checked",count>0},{"comparison_checked",count>0},{"existing_navigation_preserved",true},{"visible_windows",0},{"model_calls",0},{"source_requests",0},{"local_result_rendered",count>0||sourceCount>0}};
  File.WriteAllText(receipt,new JavaScriptSerializer().Serialize(result),Encoding.UTF8);timer.Dispose();Form.Dispose();
 }
 public void SelfTestRun(string receipt){
  forceOffline=true;OpenResearchForTest();Start();if(worker==null)throw new Exception("UI did not start its worker");var watch=Stopwatch.StartNew();
  while(!worker.HasExited){Application.DoEvents();System.Threading.Thread.Sleep(100);if(watch.Elapsed.TotalSeconds>30){Cancel();throw new Exception("Offline UI replay exceeded bound");}}
  Poll();if(last==null||S(last,"status")!="completed"||S(last,"source_requests")!="0"||S(last,"model_requests")!="0"||S(last,"result_cache_hit")!="True")throw new Exception("Actual UI worker did not reuse completed result without requests");
  SelfTest(receipt);
 }
 public void SelfTestFunctional(string receipt){forceOffline=true;OpenResearchForTest();StartComparison();if(worker==null)throw new Exception("Comparison worker missing");var watch=Stopwatch.StartNew();while(!worker.HasExited){Application.DoEvents();System.Threading.Thread.Sleep(100);if(watch.Elapsed.TotalSeconds>30){Cancel();throw new Exception("Comparison offline replay timeout");}}Poll();if(last==null||S(last,"status")!="completed"||S(last,"source_requests")!="0"||S(last,"model_requests")!="0")throw new Exception("Comparison replay dispatched new requests");ShowFunctional();if(!detail.Text.Contains("yearly")||!detail.Text.Contains("tax")||!detail.Text.Contains("https://"))throw new Exception("Field evidence view missing");SelfTest(receipt);}
 public void SelfTestTransition(string receipt){transitionTest=true;forceOffline=false;OpenResearchForTest();Start();var watch=Stopwatch.StartNew();while(timer.Enabled||!worker.HasExited){Application.DoEvents();System.Threading.Thread.Sleep(100);if(watch.Elapsed.TotalSeconds>30){Cancel();throw new Exception("Automatic transition replay timeout");}}if(workerStarts!=2||!comparisonWorker||last==null||!last.ContainsKey("competitor_comparison")||S(last,"source_requests")!="0"||S(last,"model_requests")!="0")throw new Exception("Automatic generation-to-comparison transition missing");SelfTest(receipt);var evidence=Read(receipt);evidence["automatic_transition"]=true;evidence["real_worker_processes"]=workerStarts;evidence["generation_replayed_from_isolated_cache_fixture"]=true;File.WriteAllText(receipt,new JavaScriptSerializer().Serialize(evidence),Encoding.UTF8);}
 public void SelfTestBuyer(string receipt){forceOffline=true;OpenResearchForTest();StartBuyer();var watch=Stopwatch.StartNew();while(!worker.HasExited){Application.DoEvents();System.Threading.Thread.Sleep(100);if(watch.Elapsed.TotalSeconds>30){Cancel();throw new Exception("Buyer replay timeout");}}Poll();if(last==null||S(last,"status")!="completed"||S(last,"source_requests")!="0"||S(last,"model_requests")!="0")throw new Exception("Buyer replay dispatched requests");ShowBuyer();if(!detail.Text.Contains("ПОКУПАТЕЛЬ И СПРОС")||!detail.Text.Contains("https://"))throw new Exception("Buyer evidence not shown");SelfTest(receipt);}
 public void SelfTestBuyerTransition(string receipt){buyerTransitionTest=true;forceOffline=false;OpenResearchForTest();StartComparison();var watch=Stopwatch.StartNew();while(timer.Enabled||!worker.HasExited){Application.DoEvents();System.Threading.Thread.Sleep(100);if(watch.Elapsed.TotalSeconds>30){Cancel();throw new Exception("Buyer handoff timeout");}}if(workerStarts!=2||!buyerWorker||last==null||!last.ContainsKey("buyer_evidence")||S(last,"source_requests")!="0"||S(last,"model_requests")!="0")throw new Exception("Comparison-to-buyer handoff missing");SelfTest(receipt);var r=Read(receipt);r["automatic_buyer_handoff"]=true;r["real_worker_processes"]=2;r["fixture_scope"]="isolated comparison-cache TTL replay; no new comparison";File.WriteAllText(receipt,new JavaScriptSerializer().Serialize(r),Encoding.UTF8);}
